        ${filter.orderBy}


        purchase_receive_results.id DESC



    LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT vendors.id AS id, vendors.vendor_code AS vendorCode, vendors.name AS name, vendors.work_telephone AS workTelephone, vendors.address AS address, payment_terms.net_days AS netDay FROM vendors LEFT JOIN payment_terms ON payment_terms.id = vendors.payment_term_id INNER JOIN vendor_companies ON vendor_companies.vendor_id = vendors.id WHERE vendors.is_active = 1 AND vendor_companies.company_id = 1 ORDER BY
${filter.orderBy}
vendors.id DESC
LIMIT #{filter.page}, #{filter.rowsPerPage}

