UPDATE purchase_receive_results SET
    status = -1,
    modified = NOW(),
    modified_by = #{userId}
WHERE id = #{id}

UPDATE purchase_receive_results SET
    status = 0,
    modified = NOW(),
    modified_by = #{userId}
WHERE id = #{id}

UPDATE purchase_receive_results SET


            status = #{filter.isApproved},
            disapproved = NOW(),
            disapproved_by = #{userId}


            status = #{filter.isApproved},
            approved = NOW(),
            approved_by = #{userId}


WHERE id = #{filter.id}

